INSERT INTO "applications" ("id", "job_id", "candidate_id", "status", "score", "notes", "cover_letter", "preferred_location", "availability", "relocate", "work_type", "expected_salary", "current_salary", "notice_period", "personal_statement", "technical_skills", "soft_skills", "computer_literacy", "certifications_licenses", "declaration_agreed", "background_check_consent", "conflict_of_interest", "criminal_record", "data_privacy_consent", "offer_letter_sent_at", "created_at", "updated_at") VALUES (1, 1, 1, 'interview', NULL, NULL, 'I am writing to apply for this position at PNG NISIT. With my extensive experience in the public sector and strong track record of delivering results, I am confident I can make a meaningful contribution to NISIT''s strategic objectives. I am passionate about PNG''s development and committed to excellence in government service.', 'Port Moresby', 'Immediately', TRUE, 'full_time', 'K45,000–K55,000 per annum', 'K38,000 per annum', '2 weeks', 'Throughout my career I have been guided by a commitment to excellence, integrity, and continuous improvement. I thrive in dynamic environments where I can apply analytical rigour to complex problems and deliver measurable outcomes for the organisation and the people it serves.', '["Recruitment & Selection","HRIS Administration"]'::jsonb, '["Stakeholder Engagement","Communication"]'::jsonb, 'Advanced', 'Valid PNG Driver''s Licence; First Aid Certificate', TRUE, TRUE, TRUE, TRUE, TRUE, NULL, '2026-08-18T22:22:57.940Z'::timestamptz, '2026-08-19T02:07:00.199Z'::timestamptz) ON CONFLICT ("id") DO UPDATE SET "job_id" = EXCLUDED."job_id", "candidate_id" = EXCLUDED."candidate_id", "status" = EXCLUDED."status", "score" = EXCLUDED."score", "notes" = EXCLUDED."notes", "cover_letter" = EXCLUDED."cover_letter", "preferred_location" = EXCLUDED."preferred_location", "availability" = EXCLUDED."availability", "relocate" = EXCLUDED."relocate", "work_type" = EXCLUDED."work_type", "expected_salary" = EXCLUDED."expected_salary", "current_salary" = EXCLUDED."current_salary", "notice_period" = EXCLUDED."notice_period", "personal_statement" = EXCLUDED."personal_statement", "technical_skills" = EXCLUDED."technical_skills", "soft_skills" = EXCLUDED."soft_skills", "computer_literacy" = EXCLUDED."computer_literacy", "certifications_licenses" = EXCLUDED."certifications_licenses", "declaration_agreed" = EXCLUDED."declaration_agreed", "background_check_consent" = EXCLUDED."background_check_consent", "conflict_of_interest" = EXCLUDED."conflict_of_interest", "criminal_record" = EXCLUDED."criminal_record", "data_privacy_consent" = EXCLUDED."data_privacy_consent", "offer_letter_sent_at" = EXCLUDED."offer_letter_sent_at", "updated_at" = EXCLUDED."updated_at";
