skills" = EXCLUDED."technical_skills", "soft_skills" = EXCLUDED."soft_skills", "computer_literacy" = EXCLUDED."computer_literacy", "certifications_licenses" = EXCLUDED."certifications_licenses", "declaration_agreed" = EXCLUDED."declaration_agreed", "background_check_consent" = EXCLUDED."background_check_consent", "conflict_of_interest" = EXCLUDED."conflict_of_interest", "criminal_record" = EXCLUDED."criminal_record", "data_privacy_consent" = EXCLUDED."data_privacy_consent", "offer_letter_sent_at" = EXCLUDED."offer_letter_sent_at", "updated_at" = EXCLUDED."updated_at";
